def _commonType(*arrays):
    result_type = single
    is_complex = False
    for a in arrays:
        if issubclass(a.dtype.type, inexact):
            if isComplexType(a.dtype.type):
                is_complex = True
            rt = _realType(a.dtype.type, default=None)
            if rt is None:
                raise TypeError('array type %s is unsupported in linalg' % (a.dtype.name,))
        else:
            rt = double
        if rt is double:
